const rows = $input.all().map(i => i.json).filter(r => r.lead_id);
const by = (s) => rows.filter(r => r.status === s).length;
const weekAgo = Date.now() - 7 * 86400000;
const sentWeek = rows.filter(r => r.sent_date && new Date(r.sent_date).getTime() >= weekAgo).length;
const optOut = rows.filter(r => r.reply_label === 'unsubscribe').length;
const text = 'Vacancy Outreach weekly report\n'
  + 'Leads in total: ' + rows.length + '\n'
  + 'Waiting for approval: ' + by('new') + '\n'
  + 'Approved, not sent: ' + by('ready') + '\n'
  + 'Emails sent in the last 7 days: ' + sentWeek + '\n'
  + 'In sequence (follow-up 1 sent): ' + by('followup1') + '\n'
  + 'Replied: ' + by('replied') + '\n'
  + 'Paused: ' + by('paused') + '\n'
  + 'Opted out: ' + optOut + '\n'
  + 'Stopped: ' + by('stopped') + '\n'
  + 'No website found: ' + by('no_domain') + ', no contact found: ' + by('no_contact') + ', rejected: ' + by('rejected');
return [{ json: { text } }];
